<?php
foreach([[],[CURLOPT_NOPROXY=>'localhost,127.0.0.1'],[CURLOPT_CAINFO=>__DIR__.'/tls-ca.pem']] as $options){$c=curl_init('https://localhost:38186/api.php');curl_setopt_array($c,$options+[CURLOPT_POST=>true,CURLOPT_POSTFIELDS=>'{}',CURLOPT_RETURNTRANSFER=>true,CURLOPT_TIMEOUT=>8]);curl_exec($c);echo json_encode(['options'=>array_keys($options),'ca'=>ini_get('curl.cainfo'),'ssl'=>curl_version()['ssl_version'],'ip'=>curl_getinfo($c,CURLINFO_PRIMARY_IP),'proxyHttp'=>curl_getinfo($c,CURLINFO_HTTP_CONNECTCODE),'error'=>curl_error($c),'http'=>curl_getinfo($c,CURLINFO_HTTP_CODE)])."\n";curl_close($c);}
